question.answer:
class Tag:
    def __init__(self, kind: str, number: int) -> None:
        self.kind = kind
        self.number = number

    def __repr__(self) -> str:
        return f"Tag(kind={self.kind!r}, number={self.number!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Tag):
            return NotImplemented
        return (self.kind, self.number) == (other.kind, other.number)

    # Both fields are set once and never reassigned, so the hash cannot move.
    def __hash__(self) -> int:
        return hash((self.kind, self.number))


class Loose:
    def __init__(self, label: str) -> None:
        self.label = label

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Loose):
            return NotImplemented
        return self.label == other.label


def unhashable_error() -> str:
    try:
        {Loose("x")}
    except TypeError as problem:
        return str(problem)
    return "no error"

from collections.abc import Iterable, Iterator
from dataclasses import dataclass, field, replace
from enum import Enum, auto


class Batch:
    def __init__(self, code: str, readings: Iterable[int]) -> None:
        self.code = code
        self.readings = list(readings)

    def __repr__(self) -> str:
        return f"Batch(code={self.code!r}, readings={self.readings!r})"

    def __str__(self) -> str:
        return f"batch {self.code} holding {len(self.readings)} readings"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Batch):
            return NotImplemented
        return (self.code, self.readings) == (other.code, other.readings)

    # Defining __eq__ set __hash__ to None, so put one back by hand.
    # Hash the code alone, because readings is a list and can still change.
    def __hash__(self) -> int:
        return hash(self.code)

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, Batch):
            return NotImplemented
        return self.code < other.code

    def __len__(self) -> int:
        return len(self.readings)

    def __iter__(self) -> Iterator[int]:
        return iter(self.readings)

    def __contains__(self, value: object) -> bool:
        return value in self.readings


class Severity(Enum):
    LOW = auto()
    HIGH = auto()


@dataclass(frozen=True, order=True, slots=True)
class Sample:
    code: str
    severity: Severity = field(default=Severity.LOW, compare=False)
    readings: list[int] = field(default_factory=list, compare=False)

    def __post_init__(self) -> None:
        if not 1 <= len(self.code) <= 4:
            raise ValueError(f"code {self.code!r} must be 1 to 4 characters")


def mutable_default_error() -> str:
    try:
        @dataclass
        class Broken:
            readings: list[int] = []
    except ValueError as problem:
        return str(problem)
    return "no error"


def shallow_freeze() -> str:
    sample = Sample("S1", Severity.HIGH, [1, 2])
    sample.readings.append(3)
    try:
        sample.code = "S2"
    except Exception as problem:
        return f"{sample.readings} but code is frozen: {type(problem).__name__}"
    return "nothing was frozen"

